 FOR r IN SELECT * FROM jsonb_to_recordset('[{"id":"8263a26a-bd8f-4d20-9d49-dc4943e5746e","unit":"d48d50b0-d7c4-47b4-854e-c8944618add9","grade":5,"n":4,"title":"النحو والبناء اللغوي — الفصل الأول","passage":"في الصفوف الأساسية المتوسطة، الصف 5، ضمن «الفصل الدراسي الأول — مجالات اللغة العربية». بطاقة مهارة «النحو والبناء اللغوي — الفصل الأول». مثال أصلي للصف الأساسي: «الحديقةُ جميلةٌ» جملة اسمية مبتدؤها «الحديقةُ» وخبرها «جميلةٌ». وفي «زار التلاميذُ المكتبةَ» فعل وفاعل ومفعول به. يتحقق المتعلم من نوع الجملة وعلاقة الكلمات قبل تغيير الضبط أو استعمال المثال في كتابة من إنشائه.","question":"ما إعراب «الحديقةُ» في «الحديقة جميلة»؟","correct":"مبتدأ مرفوع","wrong":["مفعول به منصوب","اسم مجرور","فعل ماض"],"practice":"كوّن جملتين اسميتين وجملتين فعليتين من بيئتك، واضبط المبتدأ أو الفاعل.","old":"DADYOOM_PS_OFFICIAL_2026_2027_V1"},{"id":"b43fcf89-2eb9-4cbb-a475-21750f98f0d5","unit":"d48d50b0-d7c4-47b4-854e-c8944618add9","grade":5,"n":5,"title":"الإملاء والخط — الفصل الأول","passage":"في الصفوف الأساسية المتوسطة، الصف 5، ضمن «الفصل الدراسي الأول — مجالات اللغة العربية». بطاقة مهارة «الإملاء والخط — الفصل الأول». أمثلة من ضاديوم: «أخذ» مبدوءة بهمزة قطع، و«استمع» مبدوءة بهمزة وصل، و«مدرسة» تنتهي بتاء مربوطة، و«بيت» بتاء مفتوحة. تساعد المراجعة بالنطق والوصل والوقف على تمييز الرسم الصحيح، ثم يعيد المتعلم كتابة جملة بخط واضح.","question":"أي كلمة تبدأ بهمزة وصل؟","correct":"استمع","wrong":["أحمد","أخذ","إبراهيم"],"practice":"اكتب ست كلمات تبدأ بهمزة وصل أو قطع، وصغ سؤالًا وجملة خبرية مع الترقيم الصحيح.","old":"DADYOOM_PS_OFFICIAL_2026_2027_V1"},{"id":"5fa1e371-d590-426f-94c2-1123c5228a11","unit":"d48d50b0-d7c4-47b4-854e-c8944618add9","grade":5,"n":6,"title":"الكتابة والتعبير — الفصل الأول","passage":"في الصفوف الأساسية المتوسطة، الصف 5، ضمن «الفصل الدراسي الأول — مجالات اللغة العربية». بطاقة مهارة «الكتابة والتعبير — الفصل الأول». مثال إنشاء مستقل: «يحتاج نشاط قراءة في مكتبة المدرسة إلى هدف واضح وأدوار مناسبة وتقييم بعد التنفيذ». يحدد الكاتب القارئ والغرض ثم يضيف تفصيلين وشاهدًا من تجربة متخيلة معلّمة بوضوح، ويختم بفكرة مرتبطة بالمقدمة. يُراجع الترابط والإملاء ولا ينسب نتائج أو اقتباسات غير مثبتة إلى جهة رسمية.","question":"ما العنصر الذي يجعل فقرة التعبير مترابطة؟","correct":"جملة موضوعية وتفاصيل داعمة وخاتمة","wrong":["تكرار العنوان فقط","حذف علامات الترقيم","ذكر نتيجة بلا دليل"],"practice":"اكتب فقرة من ست جمل عن نشاط قراءة في مكتبة المدرسة مع سبب ونتيجة ومراجعة لغوية.","old":"DADYOOM_PS_OFFICIAL_2026_2027_V1"},{"id":"44a86669-636f-4002-bfcf-c15021d89400","unit":"17f83c8b-147d-4b3b-afe1-b3704faacd40","grade":5,"n":4,"title":"النحو والبناء اللغوي — الفصل الثاني","passage":"في الصفوف الأساسية المتوسطة، الصف 5، ضمن «الفصل الدراسي الثاني — مجالات اللغة العربية». بطاقة مهارة «النحو والبناء اللغوي — الفصل الثاني». مثال أصلي للصف الأساسي: «الحديقةُ جميلةٌ» جملة اسمية مبتدؤها «الحديقةُ» وخبرها «جميلةٌ». وفي «زار التلاميذُ المكتبةَ» فعل وفاعل ومفعول به. يتحقق المتعلم من نوع الجملة وعلاقة الكلمات قبل تغيير الضبط أو استعمال المثال في كتابة من إنشائه.","question":"ما إعراب «الحديقةُ» في «الحديقة جميلة»؟","correct":"مبتدأ مرفوع","wrong":["مفعول به منصوب","اسم مجرور","فعل ماض"],"practice":"كوّن جملتين اسميتين وجملتين فعليتين من بيئتك، واضبط المبتدأ أو الفاعل.","old":"DADYOOM_PS_OFFICIAL_2026_2027_V1"},{"id":"86e533a9-1217-4131-ba40-7b45eabe7e47","unit":"17f83c8b-147d-4b3b-afe1-b3704faacd40","grade":5,"n":5,"title":"الإملاء والخط — الفصل الثاني","passage":"في الصفوف الأساسية المتوسطة، الصف 5، ضمن «الفصل الدراسي الثاني — مجالات اللغة العربية». بطاقة مهارة «الإملاء والخط — الفصل الثاني». أمثلة من ضاديوم: «أخذ» مبدوءة بهمزة قطع، و«استمع» مبدوءة بهمزة وصل، و«مدرسة» تنتهي بتاء مربوطة، و«بيت» بتاء مفتوحة. تساعد المراجعة بالنطق والوصل والوقف على تمييز الرسم الصحيح، ثم يعيد المتعلم كتابة جملة بخط واضح.","question":"أي كلمة تبدأ بهمزة وصل؟","correct":"استمع","wrong":["أحمد","أخذ","إبراهيم"],"practice":"اكتب ست كلمات تبدأ بهمزة وصل أو قطع، وصغ سؤالًا وجملة خبرية مع الترقيم الصحيح.","old":"DADYOOM_PS_OFFICIAL_2026_2027_V1"},{"id":"a719f687-8bd5-4b00-b709-ab7d2ec66271","unit":"17f83c8b-147d-4b3b-afe1-b3704faacd40","grade":5,"n":6,"title":"الكتابة والتعبير — الفصل الثاني","passage":"في الصفوف الأساسية المتوسطة، الصف 5، ضمن «الفصل الدراسي الثاني — مجالات اللغة العربية». بطاقة مهارة «الكتابة والتعبير — الفصل الثاني». مثال إنشاء مستقل: «يحتاج نشاط قراءة في مكتبة المدرسة إلى هدف واضح وأدوار مناسبة وتقييم بعد التنفيذ». يحدد الكاتب القارئ والغرض ثم يضيف تفصيلين وشاهدًا من تجربة متخيلة معلّمة بوضوح، ويختم بفكرة مرتبطة بالمقدمة. يُراجع الترابط والإملاء ولا ينسب نتائج أو اقتباسات غير مثبتة إلى جهة رسمية.","question":"ما العنصر الذي يجعل فقرة التعبير مترابطة؟","correct":"جملة موضوعية وتفاصيل داعمة وخاتمة","wrong":["تكرار العنوان فقط","حذف علامات الترقيم","ذكر نتيجة بلا دليل"],"practice":"اكتب فقرة من ست جمل عن نشاط قراءة في مكتبة المدرسة مع سبب ونتيجة ومراجعة لغوية.","old":"DADYOOM_PS_OFFICIAL_2026_2027_V1"},{"id":"cf90ab78-7680-49f5-b13a-930a914b1b85","unit":"fe3a5d3b-9c48-4633-b905-af369f3daff0","grade":6,"n":4,"title":"النحو والبناء اللغوي — الفصل الأول","passage":"في الصفوف الأساسية المتوسطة، الصف 6، ضمن «الفصل الدراسي الأول — مجالات اللغة العربية». بطاقة مهارة «النحو والبناء اللغوي — الفصل الأول». مثال أصلي للصف الأساسي: «الحديقةُ جميلةٌ» جملة اسمية مبتدؤها «الحديقةُ» وخبرها «جميلةٌ». وفي «زار التلاميذُ المكتبةَ» فعل وفاعل ومفعول به. يتحقق المتعلم من نوع الجملة وعلاقة الكلمات قبل تغيير الضبط أو استعمال المثال في كتابة من إنشائه.","question":"ما إعراب «الحديقةُ» في «الحديقة جميلة»؟","correct":"مبتدأ مرفوع","wrong":["مفعول به منصوب","اسم مجرور","فعل ماض"],"practice":"كوّن جملتين اسميتين وجملتين فعليتين من بيئتك، واضبط المبتدأ أو الفاعل.","old":"DADYOOM_PS_OFFICIAL_2026_2027_V1"},{"id":"92698151-0156-4ee5-8b58-f10a413bff17","unit":"fe3a5d3b-9c48-4633-b905-af369f3daff0","grade":6,"n":5,"title":"الإملاء والخط — الفصل الأول","passage":"في الصفوف الأساسية المتوسطة، الصف 6، ضمن «الفصل الدراسي الأول — مجالات اللغة العربية». بطاقة مهارة «الإملاء والخط — الفصل الأول». أمثلة من ضاديوم: «أخذ» مبدوءة بهمزة قطع، و«استمع» مبدوءة بهمزة وصل، و«مدرسة