أو أكاديمي منظم.","question":"ما وظيفة «تقريرًا» في «راجع المتعلم تقريرًا دقيقًا»؟","correct":"مفعول به منصوب","wrong":["فاعل مرفوع","مضاف إليه","خبر إن"],"practice":"اكتب ثلاث جمل تتصل بـمشروع مدرسي للقراءة والتواصل وأعرب المفعول به واسم إن وخبرها.","old":"DADYOOM_PS_OFFICIAL_2026_2027_V1"},{"id":"19483587-bb0f-4f22-a063-a69dd71dce4d","unit":"b1ee388f-6dd5-4992-ae2c-25f8ad0c7af5","grade":12,"n":6,"title":"التعبير والكتابة — العلمي","passage":"في المرحلة الثانوية، الصف 12، ضمن «مسار العلمي — اللغة العربية». بطاقة مهارة «التعبير والكتابة — العلمي». مثال إنشاء مستقل: «يحتاج مشروع مدرسي للقراءة والتواصل إلى هدف واضح وأدوار مناسبة وتقييم بعد التنفيذ». يحدد الكاتب القارئ والغرض ثم يضيف تفصيلين وشاهدًا من تجربة متخيلة معلّمة بوضوح، ويختم بفكرة مرتبطة بالمقدمة. يُراجع الترابط والإملاء ولا ينسب نتائج أو اقتباسات غير مثبتة إلى جهة رسمية.","question":"ما العنصر الذي يجعل فقرة التعبير مترابطة؟","correct":"جملة موضوعية وتفاصيل داعمة وخاتمة","wrong":["تكرار العنوان فقط","حذف علامات الترقيم","ذكر نتيجة بلا دليل"],"practice":"اكتب فقرة من ست جمل عن مشروع مدرسي للقراءة والتواصل مع سبب ونتيجة ومراجعة لغوية.","old":"DADYOOM_PS_OFFICIAL_2026_2027_V1"},{"id":"d128d931-8ef8-4a9b-8045-73aa0a67ccfd","unit":"6921bbec-af94-4633-abb7-affac8161df4","grade":12,"n":4,"title":"النحو والصرف — العلوم الإنسانية","passage":"في المرحلة الثانوية، الصف 12، ضمن «مسار العلوم الإنسانية — اللغة العربية». بطاقة مهارة «النحو والصرف — العلوم الإنسانية». في تدريب لغوي مستقل حول مشروع مدرسي للقراءة والتواصل: «راجعَ المتعلمُ تقريرًا دقيقًا» فعل متعدٍّ؛ و«التقريرُ واضحٌ» جملة اسمية، و«إنَّ التقريرَ واضحٌ» ناسخ. نحدد وظيفة الكلمات من العامل والقرائن قبل صياغة نص مهني أو أكاديمي منظم.","question":"ما وظيفة «تقريرًا» في «راجع المتعلم تقريرًا دقيقًا»؟","correct":"مفعول به منصوب","wrong":["فاعل مرفوع","مضاف إليه","خبر إن"],"practice":"اكتب ثلاث جمل تتصل بـمشروع مدرسي للقراءة والتواصل وأعرب المفعول به واسم إن وخبرها.","old":"DADYOOM_PS_OFFICIAL_2026_2027_V1"},{"id":"3d4e00b9-34ce-44fc-b562-05c036383294","unit":"6921bbec-af94-4633-abb7-affac8161df4","grade":12,"n":6,"title":"التعبير والكتابة — العلوم الإنسانية","passage":"في المرحلة الثانوية، الصف 12، ضمن «مسار العلوم الإنسانية — اللغة العربية». بطاقة مهارة «التعبير والكتابة — العلوم الإنسانية». مثال إنشاء مستقل: «يحتاج مشروع مدرسي للقراءة والتواصل إلى هدف واضح وأدوار مناسبة وتقييم بعد التنفيذ». يحدد الكاتب القارئ والغرض ثم يضيف تفصيلين وشاهدًا من تجربة متخيلة معلّمة بوضوح، ويختم بفكرة مرتبطة بالمقدمة. يُراجع الترابط والإملاء ولا ينسب نتائج أو اقتباسات غير مثبتة إلى جهة رسمية.","question":"ما العنصر الذي يجعل فقرة التعبير مترابطة؟","correct":"جملة موضوعية وتفاصيل داعمة وخاتمة","wrong":["تكرار العنوان فقط","حذف علامات الترقيم","ذكر نتيجة بلا دليل"],"practice":"اكتب فقرة من ست جمل عن مشروع مدرسي للقراءة والتواصل مع سبب ونتيجة ومراجعة لغوية.","old":"DADYOOM_PS_OFFICIAL_2026_2027_V1"}]'::jsonb)
 AS x(id uuid,unit uuid,grade integer,n integer,title text,passage text,question text,
 correct text,wrong text[],practice text,old text)
 LOOP
 SELECT l.id,l.content INTO STRICT target_id,old_content
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula c ON c.id=g.curriculum_id JOIN public.countries co ON co.id=c.country_id
 WHERE co.code='PS' AND l.id=r.id AND u.id=r.unit AND g.grade_number=r.grade
 AND l.title=r.title AND l.sort_order=r.n AND l.status='published'
 FOR UPDATE OF l;
 SELECT count(*) INTO used_count FROM public.student_lesson_progress WHERE lesson_id=target_id;
 IF used_count<>0 THEN RAISE EXCEPTION 'PS_PROGRESS_EXISTS_%',r.title; END IF;
 SELECT count(*) INTO used_count FROM public.lesson_activity_attempts att JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
 IF used_count<>0 THEN RAISE EXCEPTION 'PS_ATTEMPTS_EXIST_%',r.title; END IF;
 IF char_length(coalesce(old_content,''))>=350 THEN RAISE EXCEPTION 'PS_CONTENT_ALREADY_ENRICHED_%',r.title; END IF;
 SELECT count(*) INTO nacts FROM public.lesson_activities WHERE lesson_id=target_id AND content->>'origin'=r.old;
 IF nacts<>3 THEN RAISE EXCEPTION 'PS_EXPECTED_THREE_ACTIVITIES_%',r.title; END IF;
 SELECT count(*) INTO nacts FROM public.lesson_activities WHERE lesson_id=target_id AND content->>'origin'=r.old
 AND ((activity_order IN (1,2) AND activity_type='multiple_choice') OR (activity_order=3 AND activity_type IN ('reading','speaking','writing','listening')));
 IF nacts<>3 THEN RAISE EXCEPTION 'PS_ACTIVITY_SHAPE_CHANGED_%',r.title; END IF;

 UPDATE public.lessons SET content='ضاديوم — بطاقة تدريب أصلية لمجال مهاري في الصف '||r.grade::text
 ||' بالمنهج الفلسطيني. هذه البطاقة ليست فصلًا أو درسًا تفصيليًا من الكتاب الوزاري؛ مطابقة قائمة الدروس والنصوص الأصلية ما زالت تحتاج التثبت من فهارس الكتب.'
 ||E'\n\n'||'عنوان بطاقة المهارة: '||r.title
 ||E'\n\n'||'شرح وتطبيق مستقل: '||r.passage
 ||E'\n\n'||'سؤال الاستيعاب: '||r.question
 ||E'\n\n'||'مهمة إنتاج: '||r.practice
 ||E'\n\n'||'مستويات التعلم: يقرأ المبتدئ المثال ويحدد المفهوم، ويعلل المتوسط اختياره بدليل، ويقارن المتقدم مثالين ويناقش دقة التعميم؛ تراجع الكتابة مع المعلم.'
 ||E'\n\n'||'المحتوى السابق المحفوظ: '||coalesce(old_content,''),
 updated_at=now() WHERE id=target_id;

 UPDATE public.lesson_activities SET prompt=r.question,
 content=content||jsonb_build_object('origin','DADYOOM_PS_COMPETENCY_ORIGINAL_62_20261009','previousOrigin',r.old,
 'notOfficialBook',true,'coverageLevel','competency_only','sourceVerification','pending','text',r.question,
 'options',jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])),
 answer=jsonb_build_object('correct',r.correct)
 WHERE lesson_id=target_id AND activity_order=1 AND activity_type='multiple_choice' AND content->>'origin'=r.old;

 UPDATE public.lesson_activities SET prompt='ما النشاط المناسب لتطبيق مجال «'||r.title||'»؟',
 content=content||jsonb_build_object('origin','DADYOOM_PS_COMPETENCY_ORIGINAL_62_20261009','previousOrigin',r.old,
 'notOfficialBook',true,'coverageLevel','competency_only','sourceVerification','pending',
 'text','ما النشاط المناسب لتطبيق مجال «'||r.title||'»؟',
 'options',jsonb_build_array('نسخ كلمات لا علاقة لها بالدرس','إعلان نتيجة دون دليل',r.practice,'إهمال المراجعة')),
 answer=jsonb_build_object('correct',r.practice)
 WHERE lesson_id=target_id AND activity_order=2 AND activity_type='multiple_choice' AND content->>'origin'=r.old;

 UPDATE public.lesson_activities SET prompt=r.practice,
 content=content||jsonb_build_object('origin','DADYOOM_PS_COMPETENCY_ORIGINAL_62_20261009','previousOrigin',r.old,
 'notOfficialBook',true,'coverageLevel','competency_only','sourceVerification','pending',
 'text',r.passage,'practice',r.practice,'humanReviewRequired',activity_type='writing')
 WHERE lesson_id=target_id AND activity_order=3
 AND activity_type IN ('reading','writing','speaking','listening') AND content->>'origin'=r.old;

 SELECT count(*) INTO nacts FROM public.lesson_activities WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_PS_COMPETENCY_ORIGINAL_62_20261009';
 IF nacts<>3 THEN RAISE EXCEPTION 'PS_MISSING_UPDATED_ACTIVITY_%',r.title; END IF;
 END LOOP;
END $dadyoom$;